async def act(page):
    """
    From the current page state: (1) dismiss any blocking popup if present, (2) open the site's search UI
    (by clicking the search icon if available), (3) use the site's search input to search for 'crypto',
    and (4) click the third-to-last search result. The navigation click is the final action.
    """
    import re
    import asyncio

    # 1) Attempt to dismiss any visible popup/overlay that might block clicks.
    try:
        close_btns = page.get_by_role("button", name=re.compile(r"(^|\s)(close|×|x|✖)(\s|$)", re.IGNORECASE))
        if await close_btns.count() > 0:
            await close_btns.first.click()
            await asyncio.sleep(0.15)
    except Exception:
        # If dismissal fails, continue; a later click will raise a clear error if blocked.
        pass

    # 2) Click the search icon (if present) to open the site's search input/widget.
    try:
        search_icon = page.get_by_role("link", name="")
        if await search_icon.count() > 0:
            await search_icon.first.click()
            await asyncio.sleep(0.25)
    except Exception:
        # If the icon isn't present or click fails, continue; search input may already be visible.
        pass

    # 3) Locate the complementary region (search area) and find a search input.
    comp = page.get_by_role("complementary")
    # If no complementary region exists, fall back to the page root for searching.
    comp_has = await comp.count()
    root_for_search = comp if comp_has > 0 else page

    search_input = None
    # Preferred: role=searchbox inside complementary
    try:
        sbox = root_for_search.get_by_role("searchbox")
        if await sbox.count() > 0:
            search_input = sbox.first
    except Exception:
        search_input = None

    if search_input is None:
        # Fallback: textbox named or labelled 'Search' inside complementary
        try:
            tb_named = root_for_search.get_by_role("textbox", name=re.compile(r"search", re.IGNORECASE))
            if await tb_named.count() > 0:
                search_input = tb_named.first
        except Exception:
            search_input = None

    if search_input is None:
        # Final fallback: any textbox on the page
        try:
            any_tb = page.get_by_role("textbox")
            if await any_tb.count() > 0:
                search_input = any_tb.nth(0)
        except Exception:
            search_input = None

    # 4) If we found a search input, fill it with 'crypto' and trigger search.
    if search_input is not None:
        await search_input.fill("crypto")
        # Prefer a button inside the complementary region whose name includes 'search'
        try:
            search_btn = root_for_search.get_by_role("button", name=re.compile(r"search", re.IGNORECASE))
            if await search_btn.count() > 0:
                await search_btn.first.click()
            else:
                # Fallback: click first button in complementary/root_for_search
                first_btn = root_for_search.get_by_role("button")
                if await first_btn.count() > 0:
                    await first_btn.first.click()
                else:
                    # Last resort: press Enter in the input
                    await search_input.press("Enter")
        except Exception:
            # If clicking failed, press Enter as a final fallback
            try:
                await search_input.press("Enter")
            except Exception:
                # let the flow continue; the page may already be showing results
                pass

        # Wait for results to appear in main (or fallback to networkidle)
        try:
            await page.get_by_role("main").wait_for(state="visible", timeout=5000)
        except Exception:
            await page.wait_for_load_state("networkidle")

    # 5) Locate articles inside main and compute third-to-last index safely.
    main = page.get_by_role("main")
    articles = main.get_by_role("article")
    total = await articles.count()
    if total < 3:
        raise Exception(f"Expected at least 3 search results but found {total}")

    target_index = total - 3

    # Use full get_by_role path when clicking the target's link per guidance.
    target_article = page.get_by_role("main").get_by_role("article").nth(target_index)

    # 6) Prefer heading->link, then a 'Continue Reading' link, then the first link inside the article.
    # Try heading->link first
    if await target_article.get_by_role("heading").count() > 0:
        heading = target_article.get_by_role("heading").nth(0)
        if await heading.get_by_role("link").count() > 0:
            # Final action: click the heading link (may navigate away)
            await page.get_by_role("main").get_by_role("article").nth(target_index).get_by_role("heading").nth(0).get_by_role("link").nth(0).click()
            return

    # Next fallback: 'Continue Reading' link
    continue_link = target_article.get_by_role("link", name=re.compile(r"Continue Reading", re.IGNORECASE))
    if await continue_link.count() > 0:
        await page.get_by_role("main").get_by_role("article").nth(target_index).get_by_role("link", name=re.compile(r"Continue Reading", re.IGNORECASE)).nth(0).click()
        return

    # Final fallback: click the first link inside the article
    any_links = page.get_by_role("main").get_by_role("article").nth(target_index).get_by_role("link")
    if await any_links.count() == 0:
        raise Exception("No clickable link found inside the target article")
    await any_links.nth(0).click()

